import type { SVGProps } from "react";

/**
 * Exterior Products subcategory icons — converted from the client's SVG set
 * (exterior/*.svg). Like Tiles & Finishes, these keep their own literal
 * silver/metal/stone material gradients; pure-black structural fills were
 * retargeted to currentColor for brand theming, and the var(--bg,#1fbd5a)
 * "knockout" cutouts (matching the demo page's green background) were
 * retargeted to the site's cream (#F6F0E4).
 */

type IconProps = SVGProps<SVGSVGElement>;

const mergeClass = (base: string, extra?: string) => [base, extra].filter(Boolean).join(" ");

export const ExteriorIconStyles = () => (
  <style>{`
svg.ex{width:100%;height:100%;overflow:visible;color:inherit;fill:none;stroke:currentColor;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;transition:filter .35s}
svg.ex:hover{filter:drop-shadow(0 0 4px rgba(154,118,64,.35))}

@keyframes exfade{0%{opacity:0}100%{opacity:1}}
svg.ex:hover .cone,svg.ex:hover .glow{animation:exfade .5s ease forwards}
@keyframes exray{0%,100%{opacity:.35}50%{opacity:1}}
svg.ex:hover .ray{animation:exray 1s ease-in-out infinite}

@keyframes expop{0%{opacity:.35;transform:scale(.85)}100%{opacity:1;transform:scale(1)}}
svg.ex .h{transform-box:fill-box;transform-origin:center}
svg.ex:hover .h{animation:expop .5s ease-out both}
svg.ex .q{transform-box:fill-box;transform-origin:center}
svg.ex:hover .q{animation:expop .6s ease-out both}

@keyframes exkey{0%{opacity:0;transform:translateY(-10px)}40%{opacity:1;transform:translateY(0)}70%{transform:rotate(0deg)}100%{opacity:1;transform:rotate(25deg)}}
svg.ex .key{transform-box:fill-box;transform-origin:bottom center}
svg.ex:hover .key{animation:exkey 1.4s ease-in-out infinite}
@keyframes express{0%,100%{transform:rotate(0deg)}50%{transform:rotate(-18deg)}}
svg.ex .lev{transform-box:fill-box;transform-origin:center}
svg.ex:hover .lev{animation:express 1.6s ease-in-out infinite}

@keyframes exswing{0%,100%{transform:rotate(0deg)}50%{transform:rotate(6deg)}}
svg.ex .door{transform-box:fill-box;transform-origin:left center}
svg.ex:hover .door{animation:exswing 2.2s ease-in-out infinite}
svg.ex .gate{transform-box:fill-box;transform-origin:left center}
svg.ex:hover .gate{animation:exswing 2.2s ease-in-out infinite .1s}

@keyframes exsweep{0%{opacity:0;transform:translateX(-24px)}50%{opacity:.8}100%{opacity:0;transform:translateX(24px)}}
svg.ex:hover .sun{animation:exsweep 2.4s ease-in-out infinite}
svg.ex .lat{stroke-dasharray:1;stroke-dashoffset:1}
@keyframes exdraw{to{stroke-dashoffset:0}}
svg.ex:hover .lat{animation:exdraw 1.1s ease forwards}

@keyframes exsway{0%,100%{transform:rotate(-2deg)}50%{transform:rotate(2deg)}}
svg.ex .tree{transform-box:fill-box;transform-origin:bottom center}
svg.ex:hover .tree{animation:exsway 3s ease-in-out infinite}
svg.ex .canopy{transform-box:fill-box;transform-origin:center}
svg.ex:hover .canopy{animation:exsway 2.4s ease-in-out infinite .15s}
svg.ex .suc{transform-box:fill-box;transform-origin:bottom center}
svg.ex:hover .suc{animation:exsway 2.6s ease-in-out infinite}
@keyframes exfall{0%{opacity:0;transform:translate(0,-6px) rotate(0deg)}20%{opacity:1}100%{opacity:0;transform:translate(6px,16px) rotate(50deg)}}
svg.ex .fall{transform-box:fill-box;transform-origin:center;animation-play-state:paused}
svg.ex:hover .fall{animation:exfall 1.8s ease-in infinite;animation-play-state:running}
svg.ex:hover .fall.f2{animation-delay:.6s}
`}</style>
);

